@startuml

class User {
  + username : string
  + password : string
}

class Player extends User {
  + lives : int
}

class Admin extends User {
}

class Game {
  + name : string
  + minSpeed : float
  + speedIncreaseFactor : float
  + maxLength : float
  + minLength : float
}

class HallOfFame {
}

class Block {
  + color : string
  + points : int
}

class Level {
  + levelNumber : int
  + isRandom : boolean
  + startingArrangement : string[]
}

class Cell {
  + x : int
  + y : int
}

class Score {
  + totalScore : int
}

class GameSession {
  + currentScore : int
  + currentLives : int
  + isPaused : boolean
}

Admin "1" -- "*" Game : manages
Admin "0..1" -- "1" Game : is_admin_of
Player "0..*" -- "*" Game : plays
Player "1" -- "*" Score : achieves
Game "1" *-- "1" HallOfFame
Game "1" *-- "*" Level
Game "1" *-- "*" Block
Game "1" *-- "0..1" GameSession
Level "1" *-- "*" Cell
Cell "0..1" -- "0..1" Block : contains

@enduml

